@using sv_abf053e6739b465096304546755249a6.Models

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var index = i;
        var css = index == CurrentStep ? "step active"
                : CompletedSteps.Contains(index) ? "step completed"
                : "step dimmed";

        <div class="@css" @onclick="() => OnStepClick(index)">
            <span class="step-number">
                @if (CompletedSteps.Contains(index))
                {
                    <span>&#10003;</span>
                }
                else
                {
                    @(index + 1)
                }
            </span>
            <span class="step-label">@StepNames[index]</span>
        </div>

        @if (index < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(index) ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border-radius: 0.5rem;
    transition: all 0.2s;
}

.step.active {
    background: #3b82f6;
    color: white;
    font-weight: 600;
}

.step.completed {
    background: #10b981;
    color: white;
    cursor: pointer;
}

.step.completed:hover {
    background: #059669;
}

.step.dimmed {
    background: #e5e7eb;
    color: #9ca3af;
}

.step-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 50%;
    background: rgba(255,255,255,0.3);
    font-size: 0.85rem;
    font-weight: 700;
}

.step.dimmed .step-number {
    background: #d1d5db;
}

.step-label {
    font-size: 0.875rem;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e5e7eb;
}

.step-connector.completed {
    background: #10b981;
}

