.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border-radius: 0.5rem;
    transition: all 0.2s;
}

.step.active {
    background: #3b82f6;
    color: white;
    font-weight: 600;
}

.step.completed {
    background: #10b981;
    color: white;
    cursor: pointer;
}

.step.completed:hover {
    background: #059669;
}

.step.dimmed {
    background: #e5e7eb;
    color: #9ca3af;
}

.step-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 50%;
    background: rgba(255,255,255,0.3);
    font-size: 0.85rem;
    font-weight: 700;
}

.step.dimmed .step-number {
    background: #d1d5db;
}

.step-label {
    font-size: 0.875rem;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e5e7eb;
}

.step-connector.completed {
    background: #10b981;
}

