@using sv_abf053e6739b465096304546755249a6.Models

<div class="reference-form">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn-remove" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Ref.Name" @onchange="e => Update(Ref with { Name = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Ref.Relationship" @onchange="e => Update(Ref with { Relationship = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Ref.Email" @onchange="e => Update(Ref with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Ref.Phone" @onchange="e => Update(Ref with { Phone = (string?)e.Value ?? "" })" />
        </div>
    </div>
</div>

@code {
    [Parameter] public Reference Ref { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnChanged.InvokeAsync(updated);
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync();
    }
}

@using sv_abf053e6739b465096304546755249a6.Models

<div class="references-step">
    <h3>References</h3>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Ref="References[index]"
                       Index="index"
                       ShowRemove="References.Count > 2"
                       OnChanged="r => UpdateReference(index, r)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <div class="step-actions">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? ExistingReferences { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References { get; set; } = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (ExistingReferences is not null && ExistingReferences.Count > 0)
        {
            References = ExistingReferences.ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference("", "", "", ""));
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, Reference reference)
    {
        References[index] = reference;
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                errorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References.ToList());
    }
}

