@using sv_abf053e6739b465096304546755249a6.Models

<div class="review-step">
    <h3>Review & Submit</h3>

    <div class="review-section">
        <div class="section-header">
            <h4>Personal Information</h4>
            <button class="btn-edit" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="section-header">
            <h4>Work History</h4>
            <button class="btn-edit" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in Work.Entries)
        {
            <div class="work-review-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="date-range">
                    @entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="section-header">
            <h4>References</h4>
            <button class="btn-edit" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="reference-review-entry">
                <strong>@r.Name</strong> (@r.Relationship)
                <div>@r.Email · @r.Phone</div>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="section-header">
            <h4>Cover Letter</h4>
            <button class="btn-edit" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </div>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <div class="step-actions">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-submit" @onclick="HandleSubmit" disabled="@isSubmitting">
            @(isSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public WorkHistory Work { get; set; } = default!;
    [Parameter] public List<Reference> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnSubmitted { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        errorMessage = null;

        try
        {
            var application = new JobApplication(Personal, Work, References, CoverLetter);
            var applicationId = await ApplicationService.SubmitApplicationAsync(application);
            await OnSubmitted.InvokeAsync(applicationId);
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

